mapper.select:
WITH extracted AS ( SELECT r.PATIENT_ID AS patient_id, TO_CHAR(r.STAT_DATE, 'YYYY-MM-DD') AS day_str, AS period, NVL(SUBSTR(r.RCPT_NO, 1, LENGTH(r.RCPT_NO) - NVL(LENGTH(REGEXP_SUBSTR(r.RCPT_NO, '[0-9]+$')), 0)), '#') AS prefix, TO_NUMBER(REGEXP_SUBSTR(r.RCPT_NO, '[0-9]+$')) AS num_part FROM TR_OUTP_FIN_RCPT_ACCT r WHERE r.STAT_DATE BETWEEN #{startDate} AND #{endDate}
AND NVL(r.TOTAL_CHARGES, 0) >= 0
AND r.REFUNDED_RCPT_NO IS NOT NULL AND r.TOTAL_CHARGES < 0
), ordered AS ( SELECT period, CASE WHEN patient_id = LAG(patient_id) OVER (ORDER BY patient_id, day_str, prefix, num_part) AND day_str = LAG(day_str) OVER (ORDER BY patient_id, day_str, prefix, num_part) AND prefix = LAG(prefix) OVER (ORDER BY patient_id, day_str, prefix, num_part) AND num_part = LAG(num_part) OVER (ORDER BY patient_id, day_str, prefix, num_part) + 1 THEN 0 ELSE 1 END AS is_new_visit FROM extracted ) SELECT period AS "period", SUM(is_new_visit) AS "cnt" FROM ordered GROUP BY period ORDER BY period

WITH extracted AS ( SELECT r.PATIENT_ID, TO_CHAR(r.STAT_DATE, 'YYYY-MM-DD') AS day_str, r.OPERATOR_NO, NVL(SUBSTR(r.RCPT_NO, 1, LENGTH(r.RCPT_NO) - NVL(LENGTH(REGEXP_SUBSTR(r.RCPT_NO, '[0-9]+$')), 0)), '#') AS prefix, TO_NUMBER(REGEXP_SUBSTR(r.RCPT_NO, '[0-9]+$')) AS num_part FROM TR_OUTP_FIN_RCPT_ACCT r WHERE r.STAT_DATE BETWEEN #{startDate} AND #{endDate}
AND NVL(r.TOTAL_CHARGES, 0) >= 0
AND r.REFUNDED_RCPT_NO IS NOT NULL AND r.TOTAL_CHARGES < 0
), ordered AS ( SELECT OPERATOR_NO, CASE WHEN patient_id = LAG(patient_id) OVER (ORDER BY patient_id, day_str, prefix, num_part) AND day_str = LAG(day_str) OVER (ORDER BY patient_id, day_str, prefix, num_part) AND prefix = LAG(prefix) OVER (ORDER BY patient_id, day_str, prefix, num_part) AND num_part = LAG(num_part) OVER (ORDER BY patient_id, day_str, prefix, num_part) + 1 THEN 0 ELSE 1 END AS is_new_visit FROM extracted ) SELECT DECODE(OPERATOR_NO, '9101','自助机', 'C746','线上退费', '窗口') AS "name", SUM(is_new_visit) AS "cnt" FROM ordered GROUP BY DECODE(OPERATOR_NO, '9101','自助机', 'C746','线上退费', '窗口') ORDER BY "cnt" DESC

SELECT "name", NVL(SUM(amt), 0) AS "amount" FROM ( SELECT '当日挂号' AS "name", NVL(c.REGIST_FEE, 0) + NVL(c.CLINIC_FEE, 0) AS amt FROM TR_OUTP_FIN_CLINIC_MASTER c WHERE c.STAT_DATE BETWEEN #{startDate} AND #{endDate} AND c.VISIT_DATE < DATE '2025-02-08' UNION ALL SELECT CASE WHEN r.VISIT_DATE >= DATE '2025-02-08' AND r.BILL_CLASS = '1' THEN '当日挂号' ELSE '门诊缴费' END AS "name", r.TOTAL_COSTS AS amt FROM TR_OUTP_FIN_RCPT_ACCT r WHERE r.STAT_DATE BETWEEN #{startDate} AND #{endDate}
AND NVL(r.TOTAL_COSTS, 0) >= 0
AND r.REFUNDED_RCPT_NO IS NOT NULL AND r.TOTAL_COSTS < 0
) GROUP BY "name" ORDER BY "amount" DESC
